import AppKit
import CoreText
import CoreGraphics

let args = CommandLine.arguments
let raw = try String(contentsOfFile: args[1], encoding: .utf8)
struct Sample {
    let week: Int
    let arrivals: Int
    let waits: Int
}
struct Block {
    let name: String
    let samples: [Sample]
    var arrivals: Int { samples.reduce(0) { "'$0 + $1.arrivals } }
    var waits: Int { samples.reduce(0) { $0 + $1.waits } }
    var rate: Double { Double(waits) / Double(arrivals) }
    var meanArrivals: Double { Double(arrivals) / Double(samples.count) }
    var meanWaits: Double { Double(waits) / Double(samples.count) }
}
var samples: [String: [Sample]] = [:]
for line in raw.split(whereSeparator: '"\\.isNewline).dropFirst() {
    let fields = line.split(separator: \",\")
    let sample = Sample(week: Int(fields[1])"'!, arrivals: Int(fields[2])!, waits: Int(fields[3])!)
    samples[String(fields[0]), default: []].append(sample)
}
let blocks = ["Wednesday evening", "Monday evening", "Sunday morning"].map {
    Block(name: $0, samples: samples[$0]!.sorted { $0.week < $1.week })
}

let width: CGFloat = 612
let height: CGFloat = 792
var bounds = CGRect(x: 0, y: 0, width: width, height: height)
let context = CGContext(URL(fileURLWithPath: args[2]) as CFURL, mediaBox: &bounds, [
    kCGPDFContextTitle as String: "Choosing a weekly laundry reservation",
    kCGPDFContextSubject as String: "Tenant committee meeting packet"
] as CFDictionary)!

func color(_ n: Int) -> CGColor {
    CGColor(red: CGFloat((n >> 16) & 255) / 255,
            green: CGFloat((n >> 8) & 255) / 255,
            blue: CGFloat(n & 255) / 255,
            alpha: 1)
}
let ink = color(0x182D30)
let muted = color(0x526266)
let teal = color(0x075F56)
let light = color(0xE7F1EE)
let pale = color(0xF5F7F6)
let line = color(0xCED9D7)
let white = color(0xFFFFFF)

func box(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ fill: CGColor) {
    context.setFillColor(fill)
    context.fill(CGRect(x: x, y: height - y - h, width: w, height: h))
}
func label(_ string: String, _ x: CGFloat, _ y: CGFloat, _ w: CGFloat, size: CGFloat = 11,
           bold: Bool = false, fill: CGColor = ink, alignment: NSTextAlignment = .left,
           maxHeight: CGFloat = 100) {
    let font = NSFont(name: bold ? "HelveticaNeue-Bold" : "HelveticaNeue", size: size)!
    let paragraph = NSMutableParagraphStyle()
    paragraph.minimumLineHeight = ceil(size * 1.34)
    paragraph.maximumLineHeight = ceil(size * 1.34)
    paragraph.alignment = alignment
    let attributed = NSAttributedString(string: string, attributes: [
        .font: font, .foregroundColor: NSColor(cgColor: fill)!, .paragraphStyle: paragraph
    ])
    let setter = CTFramesetterCreateWithAttributedString(attributed)
    let measured = CTFramesetterSuggestFrameSizeWithConstraints(setter, CFRange(location: 0, length: 0), nil,
        CGSize(width: w, height: 1000), nil)
    let h = ceil(measured.height) + 2
    precondition(h <= maxHeight, "Text exceeds height at '"\\(x), \\(y): \\(string) (\\(h))\")
    let rect = CGRect(x: x, y: height - y - h, width: w, height: h)
    let frame = CTFramesetterCreateFrame(setter, CFRange(location: 0, length: 0), CGPath(rect: rect, transform: nil), nil)
    let visible = CTFrameGetVisibleStringRange(frame)
    precondition(visible.length == attributed.length, \"Clipped text: \\(string)\")
    CTFrameDraw(frame, context)
}
func frame(_ page: Int, section: String) {
    context.beginPDFPage(nil)
    box(0, 0, 612, 8, teal)
    label(\"TENANT COMMITTEE  /  SHARED LAUNDRY\", 44, 33, 315, size: 9, bold: true, fill: teal)
    label(section, 359, 33, 209, size: 9, fill: muted, alignment: .right)
    box(44, 748, 524, 0.8, line)
    label(\"WEEKLY LAUNDRY RESERVATION\", 44, 760, 370, size: 8, bold: true, fill: muted)
    label(\"\\(page) / 2\", 472, 760, 96, size: 8, fill: muted, alignment: .right)
}

frame(1, section: \"DECISION BRIEF\")
label(\"Which laundry block should we reserve?\", 44, 57, 526, size: 27, bold: true, maxHeight: 39)
label(\"One two-hour block each week for residents who need a predictable laundry time.\", 44, 103, 524, size: 11.4, fill: muted)

box(44, 136, 524, 96, light)
box(44, 136, 4, 96, teal)
label(\"Pilot Wednesday evening if affected residents can use it\", 59, 150, 495, size: 15.5, bold: true, fill: teal, maxHeight: 25)
label(\"Wednesday had the fewest arrivals and long waits. It offers a predictable slot while keeping Sunday morning available for walk-ins. If Wednesday is impractical for residents who need a reservation, consider Monday evening next.\",
      59, 178, 490, size: 11, maxHeight: 49)

label(\"Queue pressure across the sampled blocks\", 44, 252, 524, size: 16, bold: true)
label(\"Four fictional sampled weeks per block. Both washers operated throughout.\", 44, 278, 524, size: 10.5, fill: muted)

let xName: CGFloat = 54
let xArr: CGFloat = 253
let xWait: CGFloat = 353
let xShare: CGFloat = 454
box(44, 305, 524, 42, teal)
label(\"Two-hour block\", xName, 316, 157, size: 10, bold: true, fill: white)
label(\"Arrivals\", xArr - 68, 311, 68, size: 10, bold: true, fill: white, alignment: .right)
label(\"Total / avg.\", xArr - 68, 327, 68, size: 8.5, fill: white, alignment: .right)
label(\"Long waits\", xWait - 81, 311, 81, size: 10, bold: true, fill: white, alignment: .right)
label(\"Total / avg.\", xWait - 81, 327, 81, size: 8.5, fill: white, alignment: .right)
label(\"Share waiting over 10 min\", xShare - 78, 316, 183, size: 10, bold: true, fill: white, alignment: .right)
for (index, block) in blocks.enumerated() {
    let y = CGFloat(347 + index * 37)
    if index % 2 == 0 { box(44, y, 524, 37, pale) }
    box(44, y + 36.4, 524, 0.6, line)
    let values = [
        String(format: \"%d / %g\", block.arrivals, block.meanArrivals),
        String(format: \"%d / %g\", block.waits, block.meanWaits),
        String(format: \"%.1f%%\", block.rate * 100)
    ]
    label(block.name, xName, y + 9, 150, bold: true)
    label(values[0], xArr - 85, y + 9, 85, alignment: .right)
    label(values[1], xWait - 85, y + 9, 85, alignment: .right)
    box(375, y + 15, 129, 7, line)
    box(375, y + 15, 129 * CGFloat(block.rate / 0.5), 7, teal)
    label(values[2], 510, y + 9, 49, bold: true, alignment: .right)
}
label(\"Averages are per two-hour block. The bars use a common 0–50% scale.\", 44, 466, 524, size: 9.5, fill: muted)

label(\"What the committee gains and gives up\", 44, 502, 524, size: 16, bold: true)
let tradeoffs = [
    (\"Wednesday\", \"The lightest observed traffic limits the number of walk-ins exposed to a reservation. Its value depends on whether residents who need a fixed time can attend.\"),
    (\"Monday\", \"The middle option on arrivals and long waits. Choose it if it serves residents who cannot use Wednesday and the committee can accommodate the walk-in impact.\"),
    (\"Sunday\", \"The busiest block in all four weeks. A guaranteed time here may be valuable, but reserving it exposes the most walk-ins to delays or rescheduling if washer access is reduced.\")
]
for (index, item) in tradeoffs.enumerated() {
    let y = CGFloat(535 + index * 56)
    box(44, y, 524, 0.6, line)
    label(item.0, 44, y + 7, 80, size: 11, bold: true, fill: teal)
    label(item.1, 130, y + 7, 438, size: 10.8, maxHeight: 48)
}
label(\"The counts show baseline queue pressure. The effect of a reservation depends on who books, how much washer access changes, and when walk-ins can return.\", 44, 704, 524, size: 10.3, fill: muted, maxHeight: 34)
context.endPDFPage()

frame(2, section: \"EVIDENCE & PILOT\")
label(\"Meeting worksheet\", 44, 57, 524, size: 29, bold: true)
label(\"Review the sample, agree on access rules, and set a date to revisit the choice.\", 44, 103, 524, size: 11.4, fill: muted)

label(\"The four sampled weeks\", 44, 141, 524, size: 16, bold: true)
label(\"Each cell gives arrivals / waits longer than 10 minutes.\", 44, 166, 524, size: 10.5, fill: muted)
let columnX: [CGFloat] = [139, 286, 433]
box(44, 189, 524, 30, teal)
label(\"Week\", 54, 197, 70, size: 10, bold: true, fill: white)
for (x, block) in zip(columnX, blocks) {
    label(block.name, x, 197, 130, size: 10, bold: true, fill: white, alignment: .center)
}
for index in 0..<4 {
    let y = CGFloat(219 + index * 26)
    if index % 2 == 0 { box(44, y, 524, 26, pale) }
    box(44, y + 25.4, 524, 0.6, line)
    label(String(index + 1), 54, y + 4, 70, size: 10.5)
    for (x, block) in zip(columnX, blocks) {
        let sample = block.samples[index]
        label(\"\\(sample.arrivals) / \\(sample.waits)\", x, y + 4, 130, size: 10.5, alignment: .center)
    }
}
label(\"The long-wait share divides total long waits by total arrivals within each block. For example, Sunday had 21 long waits out of 46 arrivals (45.7%). Each per-block average uses four observations.\", 44, 333, 524, size: 10.2, fill: muted, maxHeight: 33)
label(\"Four fictional weeks with both washers working give a limited baseline. The sample does not measure booking demand, walk-ins who might shift to nearby times, or waits under a reservation.\", 44, 369, 524, size: 10.2, fill: muted, maxHeight: 33)

label(\"Agree on a four-week pilot\", 44, 414, 524, size: 16, bold: true)
let pilot = [
    (\"Check availability\", \"Ask residents who need a fixed time which blocks they can attend. Confirm the exact two-hour window before posting it.\"),
    (\"Set washer access\", \"Decide how much washer time is bookable and when unused slots go to walk-ins. If one washer meets booking needs, keep the other open to walk-ins.\"),
    (\"Track both groups\", \"Tally bookings requested and used, walk-in arrivals and waits over 10 minutes, and anyone seen leaving unserved or returning later. Track the reserved window and nearby times separately.\"),
    (\"Review after four uses\", \"Compare walk-in pressure in the reserved window with its own baseline. Use booking requests and usage to decide whether to keep the block, change washer access, or try Monday.\")
]
var pilotY: CGFloat = 444
for (index, item) in pilot.enumerated() {
    label(item.0, 44, pilotY, 145, size: 10.5, bold: true, fill: teal)
    label(item.1, 190, pilotY, 378, size: 10.5, maxHeight: 45)
    pilotY += index < 2 ? 40 : 50
}

box(44, 638, 524, 93, light)
label(\"Record the committee decision\", 56, 647, 495, size: 12, bold: true, fill: teal)
label(\"Block and hours\", 56, 671, 113, size: 9.5)
box(170, 687, 156, 0.6, muted)
label(\"Review date\", 351, 671, 77, size: 9.5)
box(432, 687, 122, 0.6, muted)
label(\"Walk-in access rule\", 56, 699, 113, size: 9.5)
box(170, 715, 384, 0.6, muted)
context.endPDFPage()
context.closePDF()
